/// <summary>Bind the uniquely verified restarted window without triggering competing auto-connect/reset jobs.</summary>
public void BindWin32RecoveryWindow(DesktopWindowInfo window)
{
    if (CurrentController != MaaControllerTypes.Win32 || window.Handle == IntPtr.Zero)
        throw new InvalidOperationException("Recovery requires a valid Win32 window.");
    var previousConnect = _suppressAutoConnect;
    var previousToast = _suppressDeviceSelectionToast;
    _suppressAutoConnect = true;
    _suppressDeviceSelectionToast = true;
    try
    {
        // ChangedDevice sees the same already-pinned handle and does not
        // schedule a background SetTasker racing the explicit reconnect.
        Processor.Config.DesktopWindow.Name = window.Name;
        Processor.Config.DesktopWindow.HWnd = window.Handle;
        Devices = new ObservableCollection<object>(new object[] { window });
        CurrentDevice = window;
        OnPropertyChanged(nameof(CurrentDevice));
        OnPropertyChanged(nameof(CurrentDeviceTooltipText));
    }
    finally
    {
        _suppressAutoConnect = previousConnect;
        _suppressDeviceSelectionToast = previousToast;
    }
    SetConnected(false);
}

